// Target tidur (jam per 24 jam, WHO 2019 & AASM 2016) & jam tidur yang disarankan.
// pukul = patokan statis; aplikasi web sebaiknya menghitung mundur dari waktu Subuh (minJam).
// bangunSubuh = apakah anak dibiasakan bangun untuk shalat Subuh.
function sleepInfo(m) {
  if (m < 4) return { jam: '14–17 jam', pukul: 'mengikuti bayi', minJam: 14, bangunSubuh: false, catatan: 'Tidur aman: telentang, di kasur sendiri di kamar orang tua.' };
  if (m < 12) return { jam: '12–16 jam (termasuk tidur siang)', pukul: '±19.00', minJam: 12, bangunSubuh: false, catatan: 'Tidur aman: telentang, di kasur sendiri di kamar orang tua.' };
  if (m < 36) return { jam: '11–14 jam (termasuk tidur siang)', pukul: '±19.00–19.30', minJam: 11, bangunSubuh: false, catatan: 'Belum perlu dibangunkan untuk Subuh; biarkan bangun sendiri.' };
  if (m < 72) return { jam: '10–13 jam (termasuk tidur siang)', pukul: '±19.30–20.00', minJam: 10, bangunSubuh: false, catatan: 'Belum perlu dibangunkan untuk Subuh; biarkan bangun sendiri.' };
  if (m < 84) return { jam: '9–12 jam', pukul: '±19.30–20.00', minJam: 9, bangunSubuh: false, catatan: 'Belum perlu dibangunkan untuk Subuh. Boleh ikut Subuh bila sudah bangun sendiri.' };
  if (m < 120) return { jam: '9–12 jam, lengkapi dengan qailulah', pukul: '±19.30–20.00', minJam: 9, bangunSubuh: true, catatan: 'Bangun Subuh ±04.30 dan tidur 20.00 baru memberi ±8,5 jam. Lengkapi dengan qailulah 20–30 menit, atau 30–60 menit di hari libur; majukan Majelis agar selesai sebelum Isya.' };
  if (m < 156) return { jam: '9–12 jam, lengkapi dengan qailulah', pukul: '±20.00–20.30', minJam: 9, bangunSubuh: true, catatan: 'Tidur 20.00–20.30 dan bangun Subuh memberi ±8–8,5 jam. Lengkapi dengan qailulah 20–30 menit, atau 30–60 menit di hari libur.' };
  return { jam: '8–10 jam, lengkapi dengan qailulah', pukul: '±21.00', minJam: 8, bangunSubuh: true, catatan: 'Lampu padam ±21.00 dan bangun Subuh memberi ±7,5 jam: tambah qailulah 20–30 menit; di hari libur boleh tidur lagi sebentar setelah dzikir pagi. Gawai diparkir di luar kamar ≥1 jam sebelum tidur, jadwal akhir pekan tidak bergeser lebih dari 1 jam, tanpa kopi atau minuman energi setelah Ashar.' };
}

// Aturan layar per usia (patokan tunggal: WHO 2019 untuk balita; PP 17/2025 "PP Tunas" untuk akun)
function screenRule(m) {
  if (m < 24) return 'Tanpa layar, kecuali video call keluarga (WHO 2019). HP orang tua juga diparkir saat menyusui, menyuapi, dan bermain; TV tidak menyala sebagai latar.';
  if (m < 60) return 'Paling banyak 1 jam sehari, lebih sedikit lebih baik, selalu ditonton bersama (WHO 2019). Konten lambat yang dipilih orang tua. Tidak punya perangkat sendiri. Pantang layar: bukan penenang tantrum, tanpa video pendek dan autoplay, tidak saat makan, tidak 1 jam sebelum tidur.';
  if (m < 84) return 'Paling banyak 1 jam sehari, ditemani. Konten pilihan; video hanya dari daftar putar yang dipilih orang tua, tanpa akun anak. Tidak punya perangkat sendiri. Pantang layar: bukan penenang tantrum, tanpa video pendek dan autoplay, tidak saat makan, tidak 1 jam sebelum tidur.';
  if (m < 120) return "Perangkat keluarga di ruang bersama, setelah Qur'an dan tugas selesai. Video ditonton tanpa akun anak dan ditemani. Tidak ada akun gim dengan chat terbuka. Tidak punya HP pribadi. Pantang layar: tanpa video pendek dan autoplay, tidak saat makan, tidak 1 jam sebelum tidur, gawai tidak masuk kamar.";
  if (m < 156) return 'Untuk belajar sesuai Kontrak Digital. Tanpa akun media sosial, YouTube, Discord, atau Telegram sendiri (PP Tunas: di bawah 13 tahun hanya layanan berisiko rendah yang dirancang untuk anak, dengan izin orang tua). Layar hiburan paling banyak 2 jam di hari libur. Filter DNS di router dan kontrol orang tua di perangkat. Pantang layar: tanpa video pendek dan autoplay, tidak saat makan, tidak 1 jam sebelum tidur, gawai tidak masuk kamar.';
  return 'HP pribadi dengan kontrol orang tua yang terbuka (anak tahu apa yang dipantau), dilonggarkan bertahap sesuai rekam jejak. PP Tunas: sebelum 16 tahun belum boleh punya akun media sosial atau platform berisiko tinggi; 13–15 tahun hanya layanan berisiko rendah dengan izin orang tua; 16–17 tahun tetap dengan izin orang tua. Tanpa AI companion. Gawai diparkir di luar kamar ≥1 jam sebelum tidur. Tidak ada rahasia yang membahayakan: bila terlanjur melihat atau melakukan yang salah, cerita dulu, diselesaikan bersama tanpa marah.';
}

